        width: size.width,
        height: size.height
      }}>{after}</View>
    </FrameView>
    <FrameView pointerEvents="none" frameStyle={() => {
      "worklet";

      return [styles.divider, {
        left: Math.max(0, size.width * motion.value[0] - 2)
